    if (s == null) {
        return null;
    }
    if (s.isEmpty()) {
        return "";
    }

    final int ALPHABET_SIZE = 65536; // Unicode
    int[] freq = new int[ALPHABET_SIZE];
    int total = 0;
    for (char c : s.toCharArray()) {
        freq[c]++;
        total++;
    }

    StringBuilder sb = new StringBuilder(total);

    while (total > 0) {
        /* Ascending phase */
        int last = -1;
        for (int ch = 0; ch < ALPHABET_SIZE && total > 0; ch++) {
            if (freq[ch] > 0 && ch > last) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
                last = ch;
            }
        }
        if (total == 0) {
            break;
        }

        /* Descending phase */
        int start = -1;
        for (int ch = ALPHABET_SIZE - 1; ch >= 0 && total > 0; ch--) {
            if (freq[ch] > 0) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
                start = ch;
                break;
            }
        }
        if (total == 0) {
            break;
        }

        for (int ch = start - 1; ch >= 0 && total > 0; ch--) {
            if (freq[ch] > 0) {
                sb.append((char) ch);
                freq[ch]--;
                total--;
            }
        }
    }

    return sb.toString();
}

