public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    char[] symDigits = {'0','1','8'};
    int half = (n + 1)/2;
    char[] arr = new char[n];
    class Helper {
        void dfs(int pos) {
            if (pos >= half) {
                result.add(new String(arr));
                return;
            }
            if (n % 2 == 1 && pos == n/2) {
                for (char d : symDigits) {
                    arr[pos] = d;
                    dfs(pos+1);
                }
                return;
            }
            for (char[] pair : pairs) {
                char left = pair[0];
                if (pos==0 && n>1 && left=='0') continue;
                char right = pair[1];
                arr[pos] = left;
                arr[n-1-pos] = right;
                dfs(pos+1);
            }
        }
    }
    new Helper().dfs(0);
    java.util.Collections.sort(result);
    return result;
}

